#include <string>
#include <unordered_set>

using namespace std;

class Solution {
public:
    int countVowelSubstrings(string word) {
        int res = 0, n = word.size();
        for (int i = 0; i < n; ++i) {
            unordered_set<char> st;
            for (int j = i; j < n; ++j) {
                if (!isVowel(word[j])) break;
                st.insert(word[j]);
                if (st.size() == 5) res++;
            }
        }
        return res;
    }

    bool isVowel(char c) {
        return string("aeiou").find(c) != string::npos;
    }
};
